    def validate(self) -> Dict[str, str]:
        """Validate all config files against schema and monotonicity rules.

        Returns:
            Dict mapping config names to "ok" or error message.
        """
        results = validate_all_policies()

        def _matches_type(value: Any, expected: str) -> bool:
            if expected == "bool":
                return isinstance(value, bool)
            if expected == "int":
                return isinstance(value, int) and not isinstance(value, bool)
            if expected == "float":
                return isinstance(value, (int, float)) and not isinstance(value, bool)
            if expected in ("string", "enum"):
                return isinstance(value, str)
            return False

        layer_rank = {name: i for i, name in enumerate(LAYER_ORDER)}

        def _validate_mapping(name: str, mapping: Dict[str, Any], layer_name: str) -> None:
            errors: List[str] = []
            for dotpath, value in _flatten_dict(mapping).items():
                defn = self._schema.get(dotpath)
                if defn is None:
                    errors.append(f"{dotpath}: not defined in schema")
                    continue
                if layer_rank[layer_name] < layer_rank[defn.min_layer]:
                    errors.append(
                        f"{dotpath}: defined in {layer_name}, but min_layer is {defn.min_layer}"
                    )
                if not _matches_type(value, defn.type):
                    errors.append(
                        f"{dotpath}: got {value!r} (type {type(value).__name__}), expected {defn.type}"
                    )
                    continue
                if defn.allowed_values is not None and value not in defn.allowed_values:
                    errors.append(
                        f"{dotpath}: got {value!r}, allowed values are {defn.allowed_values}"
                    )
            if errors:
                results[name] = "Schema validation errors:\n" + "\n".join(f"  {e}" for e in errors)
            elif results.get(name) == "ok":
                results[name] = "ok"

        # Existing coverage checks against registry invariants
        schema_hard_bools = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type == "bool"
        }
        registry_hard_bools = set(HARD_CONSTRAINTS.keys())
        missing = registry_hard_bools - schema_hard_bools
        if missing:
            results["schema_coverage/hard_bools"] = (
                f"Schema missing HARD bool constraints: {sorted(missing)}"
            )

        schema_hard_thresholds = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type in ("int", "float")
        }
        registry_hard_thresholds = set(HARD_THRESHOLDS.keys())
        missing_thresh = registry_hard_thresholds - schema_hard_thresholds
        if missing_thresh:
            results["schema_coverage/hard_thresholds"] = (
                f"Schema missing HARD threshold constraints: {sorted(missing_thresh)}"
            )

        schema_hard_strings = {
            dp for dp, defn in self._schema.items()
            if defn.constraint_class == "HARD" and defn.type == "string"
        }
        registry_hard_strings = set(HARD_STRINGS.keys())
        missing_str = registry_hard_strings - schema_hard_strings
        if missing_str:
            results["schema_coverage/hard_strings"] = (
                f"Schema missing HARD string constraints: {sorted(missing_str)}"
            )

        # Validate schema defaults
        default_errors: List[str] = []
        for dotpath, defn in sorted(self._schema.items()):
            if not _matches_type(defn.default, defn.type):
                default_errors.append(
                    f"{dotpath}: default {defn.default!r} does not match type {defn.type}"
                )
            elif defn.allowed_values is not None and defn.default not in defn.allowed_values:
                default_errors.append(
                    f"{dotpath}: default {defn.default!r} not in allowed_values {defn.allowed_values}"
                )
        if default_errors:
            results["schema/defaults"] = (
                "Schema validation errors:\n" + "\n".join(f"  {e}" for e in default_errors)
            )

        # Validate each layer file against schema
        universal_path = REGISTRY_DIR / "universal.toml"
        if universal_path.exists():
            _validate_mapping("universal", _load_toml(universal_path), "universal")

        domains_dir = REGISTRY_DIR / "domains"
        if domains_dir.exists():
            for toml_file in sorted(domains_dir.glob("*.toml")):
                _validate_mapping(
                    f"domain/{toml_file.stem}",
                    _load_toml(toml_file),
                    "domain",
                )

        tasks_dir = REGISTRY_DIR / "tasks"
        if tasks_dir.exists():
            for toml_file in sorted(tasks_dir.glob("*.toml")):
                _validate_mapping(
                    f"task/{toml_file.stem}",
                    _load_toml(toml_file),
                    "task",
                )

        models_dir = REGISTRY_DIR / "models"
        if models_dir.exists():
            for toml_file in sorted(models_dir.glob("*.toml")):
                _validate_mapping(
                    f"model/{toml_file.stem}",
                    _load_toml(toml_file),
                    "model",
                )

        return results
