            )

        configs = [("universal", REGISTRY_DIR / "universal.toml")]
        configs.extend((f"domain/{p.stem}", p) for p in sorted((REGISTRY_DIR / "domains").glob("*.toml")))
        configs.extend((f"task/{p.stem}", p) for p in sorted((REGISTRY_DIR / "tasks").glob("*.toml")))
        configs.extend((f"model/{p.stem}", p) for p in sorted((REGISTRY_DIR / "models").glob("*.toml")))

