            if expected == "bool":
                return isinstance(value, bool)
            if expected == "int":
                return isinstance(value, int) and not isinstance(value, bool)
            if expected == "float":
                return isinstance(value, (int, float)) and not isinstance(value, bool)
            if expected in ("string", "enum"):
                return isinstance(value, str)
            return False

        layer_rank = {name: i for i, name in enumerate(LAYER_ORDER)}

        def _validate_mapping(name: str, mapping: Dict[str, Any], layer_name: str) -> None:
            errors: List[str] = []
            for dotpath, value in _flatten_dict(mapping).items():
                defn = self._schema.get(dotpath)
                if defn is None:
                    errors.append(f"{dotpath}: not defined in schema")
                    continue
                if layer_rank[layer_name] < layer_rank[defn.min_layer]:
                    errors.append(
                        f"{dotpath}: defined in {layer_name}, but min_layer is {defn.min_layer}"
                    )
                if not _matches_type(value, defn.type):
                    errors.append(
                        f"{dotpath}: got {value!r} (type {type(value).__name__}), expected {defn.type}"
                    )
